const std = @import("std");
const mem = std.mem;

pub fn row(allocator: mem.Allocator, s: []const u8, index: i32) ![]i16 {
    const row_idx = std.math.cast(usize, index - 1) orelse return error.InvalidIndex;
    var lines = std.mem.splitScalar(u8, s, '\n');
    var line_idx: usize = 0;
    var target_line: []const u8 = undefined;
    var found = false;
    while (lines.next()) |line| {
        if (line_idx == row_idx) {
            target_line = line;
            found = true;
            break;
        }
        line_idx += 1;
    }
    if (!found) return error.InvalidIndex;
    var tokens = std.mem.tokenizeAny(u8, target_line, " \t\r\n");
    var count: usize = 0;
    while (tokens.next()) |_| count += 1;
    var result = try allocator.alloc(i16, count);
    defer allocator.free(result);
    var tokens2 = std.mem.tokenizeAny(u8, target_line, " \t\r\n");
    var out: usize = 0;
    while (tokens2.next()) |token| {
        result[out] = std.fmt.parseInt(i16, token, 10) catch return error.InvalidCharacter;
        out += 1;
    }
    return result;
}
```
