pub fn column(allocator: mem.Allocator, s: []const u8, index: i32) ![]i16 {
    const col_idx = std.math.cast(usize, index - 1) orelse return error.InvalidIndex;
    var lines = std.mem.splitScalar(u8, s, '\n');
    var line_idx: usize = 0;
    var count: usize = 0;
    // first pass: count tokens at col_idx in each line
    while (lines.next()) |line| {
        var tokens = std.mem.tokenizeAny(u8, line, " \t\r\n");
        var pos: usize = 0;
        while (tokens.next()) |token| {
            if (pos == col_idx) count += 1;
            pos += 1;
        }
        line_idx += 1;
    }
    var result = try allocator.alloc(i16, count);
    errdefer allocator.free(result);
    var lines2 = std.mem.splitScalar(u8, s, '\n');
    var out: usize = 0;
    while (lines2.next()) |line| {
        var tokens = std.mem.tokenizeAny(u8, line, " \t\r\n");
        var pos: usize = 0;
        while (tokens.next()) |token| {
            if (pos == col_idx) {
                result[out] = std.fmt.parseInt(i16, token, 10) catch return error.InvalidCharacter;
                out += 1;
            }
            pos += 1;
        }
    }
    return result;
}
```
